"""Build a compact report and source/data bundle for the selected-case confirmation."""
import base64,hashlib,html,json,subprocess,sys,zipfile
from pathlib import Path
repo,p=map(Path,sys.argv[1:3]);a=json.loads((p/'analysis.json').read_text());m=json.loads((p/'manifest.json').read_text())
for name in ['ledger-verification.json','independent-recomputation.json']:assert json.loads((p/name).read_text())['status']=='passed'
esc=html.escape
def n(v):return f'{v:+.3f}'
def ci(v):return n(v[0])+' to '+n(v[1])
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(v)+'</th>'for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(str(v))+'</td>'for v in row)+'</tr>'for row in rows)+'</tbody></table></div>'
def arm(id):return {'temperate':'18 C, mean tolerance','t35-normal-035':'35 C, normal 0.35','t35-shared':'35 C, mean tolerance','t28-normal-050':'28 C, normal 0.50','t28-normal-035':'28 C, normal 0.35'}[id]
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig,ax=plt.subplots(figsize=(9,4.8),layout='constrained');labels=['Dover: 35 C normal 0.35\nversus 18 C mean tolerance','Norfolk: 35 C normal 0.35\nversus mean tolerance','Anacostia: 28 C normal traits\n0.35 versus 0.50']
for i,b in enumerate(a['cases']):
 r=b['fresh'];x=r['winChangePoints'];ax.errorbar(x,i,xerr=[[x-r['winInterval'][0]],[r['winInterval'][1]-x]],fmt='o',color='#117b72',capsize=5,markersize=7,label='Fresh estimate, family 95% interval'if i==0 else None)
 ax.scatter(b['screen']['winChangePoints'],i,marker='D',s=50,facecolors='none',edgecolors='#b66a28',linewidths=1.6,label='Selected screening estimate'if i==0 else None)
ax.axvline(0,color='#7b8991',linewidth=1);ax.set_yticks(range(3),labels);ax.invert_yaxis();ax.set_ylim(2.6,-.6);ax.set_xlabel('Change in focal-club win probability (percentage points)');ax.set_title('Fresh confirmation of selected screening flags',loc='left',weight='bold');ax.grid(axis='x',alpha=.2);ax.spines[['top','right']].set_visible(False);ax.legend(loc='lower right',fontsize=8)
fig.text(.02,-.04,'4,096 fresh matched seeds per case; three-case family-protected intervals.\nScreen estimates selected for review; no screening outcomes pooled into confirmation.',fontsize=9,color='#435462')
fig.savefig(p/'Temperature_Tolerance_Confirmation.png',dpi=180,bbox_inches='tight');fig.savefig(p/'Temperature_Tolerance_Confirmation.svg',bbox_inches='tight');plt.close(fig)
s='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Century temperature and tolerance confirmation</title><style>body{font:17px/1.6 system-ui;background:#edf3f3;color:#18333e;margin:0}main{max-width:1200px;margin:24px auto;background:white;padding:30px;border-radius:14px}h1,h2{color:#155264;line-height:1.25}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px;text-align:left;border-bottom:1px solid #d4e1e5}th{background:#155264;color:white}tr:nth-child(even){background:#f2f7f8}.note{padding:16px;background:#edf7f3;border-left:4px solid #16735e}@media(max-width:650px){main{margin:0;padding:16px}table{font-size:12px}}</style><main><h1>Fresh temperature/tolerance confirmation</h1>'''
s+='<p>Completed November 14, 2026: <strong>4,096 fresh matched seeds per selected case; 12,288 fixture clusters and 24,576 outcomes</strong>. Both arms share each seed, with 2,048 fixtures on each simulation side. Fixed copied squads, original tactics, healthy availability and exact player traits; 80% humidity, no wind/rain and disabled psychology. No coefficient or official-record changes.</p>'
s+='<div class="note">'+''.join('<p>'+esc(v)+'</p>'for v in (p/'assessment.txt').read_text().strip().split('\n\n'))+'</div>'
s+='<img alt="Fresh winner effects and selected screening estimates" style="max-width:100%;height:auto" src="data:image/png;base64,'+base64.b64encode((p/'Temperature_Tolerance_Confirmation.png').read_bytes()).decode()+'">'
s+='<h2>Primary: candidate minus reference winner change</h2><p>Positive means the first named club benefits. Conservative Bonferroni/Wilson discordance intervals protect the three-case family; two arms and reciprocal views are not extra independent observations. The earlier screen is shown separately, not pooled.</p>'
s+=table(['Focal / opponent','Reference → candidate','Selected screen, pp','Fresh change, pp','Fresh family 95%'],[[b['focal']+' / '+b['opponent'],arm(b['reference'])+' → '+arm(b['candidate']),n(b['screen']['winChangePoints']),n(b['fresh']['winChangePoints']),ci(b['fresh']['winInterval'])]for b in a['cases']])
s+='<h2>Within-arm records and paired discordances</h2><p>Within-arm percentages are descriptive. Paired changed-winner counts govern the primary contrast. Secondary score-margin intervals use approximate Bonferroni protection across the three cases.</p>'
s+=table(['Focal club','Reference wins','Candidate wins','Changed to focal','Changed against focal','Unchanged winner','Margin change (family 95%)'],[[b['focal'],f"{int(b['cells']['reference']['wins'])}/4096 ({b['cells']['reference']['winRatePct']:.3f}%)",f"{int(b['cells']['candidate']['wins'])}/4096 ({b['cells']['candidate']['winRatePct']:.3f}%)",b['fresh']['changedToFocal'],b['fresh']['changedAgainstFocal'],b['fresh']['unchangedWinner'],n(b['fresh']['scoreMargin']['mean'])+' ('+ci(b['fresh']['scoreMargin']['interval'])+')']for b in a['cases']])
s+='<h2>Simulation-side checks</h2><p>These side-specific intervals are nominal per contrast and exploratory. An apparent difference between sides needs a direct interaction study; one interval crossing zero while another does not is not proof of a difference.</p>'
s+=table(['Focal club','Focal on side 0: win change (95%)','Focal on side 1: win change (95%)'],[[b['focal']]+[n(v['values']['winChangePoints'])+' ('+ci(v['values']['winInterval'])+')'for v in b['sides']]for b in a['cases']])
s+='<h2>Physical response and denominators</h2><p>Energy uses a 0–100 scale. Active energy is time-weighted; final energy is the squad average. Requested extra fatigue is the model budget before the energy floor, not measured physiology. No direct heat-only kick penalty is applied; energy can affect upstream execution quality.</p>'
rows=[]
for b in a['cases']:
 for key in ['reference','candidate']:
  for role,name in [('focal',b['focal']),('opponent',b['opponent'])]:
   v=b['cells'][key]['clubs'][role];rows.append([b['focal']+' case',name,key,f"{100*v['activeEnergy']:.3f}",f"{100*v['meanFinalEnergy']:.3f}",f"{v['extraFatiguePer1000PlayerSeconds']:.4f}",v['kickChecks'],f"{v['shotsPerMinute']:.4f}"])
s+=table(['Case','Club','Arm','Active energy','Final energy','Extra fatigue / 1,000 player-seconds','Kick checks','Shots/minute'],rows)
s+=table(['Focal club','Paired active-energy change (nominal 95%)','Duration change, minutes (nominal 95%)','Combined-score change (nominal 95%)'],[[b['focal']]+[n(b['fresh'][key]['mean'])+' ('+ci(b['fresh'][key]['interval'])+')'for key in ['activeEnergyPoints','durationMinutes','combinedScore']]for b in a['cases']])
s+='<h2>Fresh minus selected screening estimates</h2><p>These exploratory independent-sample differences are descriptive after screening selection. They do not establish a true change in the model or prove that an earlier ledger was wrong.</p>'
s+=table(['Focal club','Fresh minus screen, pp','Exploratory nominal 95%'],[[b['focal'],n(b['freshMinusScreen']['winChangePoints']),ci(b['freshMinusScreen']['nominal95'])]for b in a['cases']])
s+='<h2>Verification, reproducibility and limits</h2><p>Preflight: 12 arm/side constructions, six exact neutral/v1.0 checks, four historical result replays, full save/resume of 12 outcomes, case/profile mismatch rejection and corrupted-telemetry rejection. Research: 12 enabled full replays and two Dover neutral/v1.0 controls. Every retained outcome passed input, score, statistic, clock and checksum checks. The complete post-run audit verified all gzip CRCs, result hashes and compact records. Independent Python recomputation verified the primary winner family, margins, sides, physical denominators and separate screen comparisons. All 64 frozen v1.0 files remained intact.</p><p>The compact bundle preserves every outcome record, exact traits, fixed plan, manifests, ledger checksum index, verification and pinned source. Full ledgers remain separate; bulk delivery is deferred. No official player records, coaches, rules, results, defaults or deployment changed.</p><p>Limits: selected matchups, temperatures and one fixed trait population; no cold-response validation, league-wide ceiling, normal-trait acceptance budget, full psychological/weather stack or halftime adaptation. The eight-point weather review level is contextual for the Dover contrast; it is not an automatic acceptance threshold for the Norfolk trait or Anacostia coefficient comparison. The 0.35 setting remains provisional.</p></main></html>'
(p/'Century_Temperature_Tolerance_Confirmation.html').write_text(s)
repro=p/'reproduction';base='1f867ad5de47a6e8c40b70cbcb379e8751c72e8a';(repro/'base-commit.txt').write_text(base+'\n');(repro/'source.patch').write_bytes(subprocess.check_output(['git','diff','--binary',base,'HEAD'],cwd=repo));(repro/'pinned-commit.txt').write_bytes(subprocess.check_output(['git','rev-parse','HEAD'],cwd=repo))
for name in ['audit-temperature-confirmation.mjs','analyze-temperature-confirmation.py','recompute-temperature-confirmation.py','report-temperature-confirmation.py']:(repro/name).write_bytes((repo/'scripts'/name).read_bytes())
(repro/'README.txt').write_text('\n'.join(['Reconstruct Golfhaus/CenturyLeague at base-commit.txt, then git apply --binary source.patch. Use Node '+m['runtime']['node']+' and the saved simulation command under scripts/supervise-engine-study.py. Exact manifest source fingerprint required; no official credentials needed. Full ledgers are not included, their checksums are retained.',
 'To recompute the compact confirmation from this extracted directory without simulations:', 'python3 reproduction/analyze-temperature-confirmation.py .','python3 reproduction/recompute-temperature-confirmation.py .','Screening sample stays separate in prior-comparison. No official deployment or adoption.','']))
files=sorted(x for x in p.rglob('*')if x.is_file()and x.suffix!='.zip'and x.name not in ['CHECKSUMS.sha256','save-status.json','save-receipt.json']and not x.name.endswith('.log'))
(p/'CHECKSUMS.sha256').write_text(''.join(hashlib.sha256(x.read_bytes()).hexdigest()+'  '+x.relative_to(p).as_posix()+'\n'for x in files));z=p/'Century_Temperature_Tolerance_Confirmation_2026_11_14.zip'
with zipfile.ZipFile(z,'w',zipfile.ZIP_DEFLATED,compresslevel=9)as f:
 for x in files+[p/'CHECKSUMS.sha256']:f.write(x,x.relative_to(p).as_posix())
with zipfile.ZipFile(z)as f:
 assert f.testzip()is None
 for line in f.read('CHECKSUMS.sha256').decode().splitlines():
  sha,name=line.split('  ',1);assert hashlib.sha256(f.read(name)).hexdigest()==sha
print(json.dumps({'status':'verified','package':str(z.resolve()),'bytes':z.stat().st_size,'contentFiles':len(files)}))
